import{apiClient}from"./client";const sendTradeInRequest=async a=>{return(await apiClient.post("/trade-in",a)).data},uploadTradeInImage=async a=>{const e=new FormData;return e.append("file",a),(await apiClient.post("/admin/media/images",e,{headers:{"Content-Type":"multipart/form-data"}})).data.url};export{sendTradeInRequest,uploadTradeInImage};